xml.Script:
        Colors[0] := 'FF0080'; 
        Colors[1] := 'F80000'; 
        Colors[2] := 'F67F05'; 
        Colors[3] := 'FFFF00'; 
        Colors[4] := '005600'; 
        Colors[5] := '000078'; 

        sColors[ 0] := '     5303          ';
        sColors[ 1] := '     3535          ';
        sColors[ 2] := '     5352          ';
        sColors[ 3] := '     4131          ';
        sColors[ 4] := '5354 4131 1253 3035';
        sColors[ 5] := '4545 5414 4020 0304';
        sColors[ 6] := '0454 4140 0202 2030';
        sColors[ 7] := '2521 1412 2120 0312';
        sColors[ 8] := '     1412          ';
        sColors[ 9] := '     2121          ';
        sColors[10] := '     5212          ';
        sColors[11] := '     2130          ';

        W := 0.5;
        D := W / 3;
        D2 := D * 2;

        N := 12;
        step := W * 2 / N; // minimal step in coordinates
        cv := 0; // Vertex Count

        function GetId(xc, yc);
        begin
            xc := xc + i * 4;
            yc := yc + j * 4;
            xi := x + dx1 * xc + dx2 * yc;
            yi := y + dy1 * xc + dy2 * yc;
            zi := z + dz1 * xc + dz2 * yc;
            if VarExists('Idx[' + IntToStr(xi) + ',' + IntToStr(yi) + ',' + IntToStr(zi) + ']') then
                Result := Idx[xi, yi, zi]
            else begin
                Vx[cv] := xi * step - W;
                Vy[cv] := yi * step - W;
                Vz[cv] := zi * step - W;
                Result := IntToStr(cv) + ';';
                Idx[xi, yi, zi] := Result;
                Inc(cv);
            end;
        end;

        function GetColor(x3, y3);
        begin
            char := copy(sColors[sy + y3 + j], sx + x3 + i, 1);
            Result := Colors[StrToInt(char)];
        end;

        procedure Polygon(ids, ies);
        begin
            S[cf] := ids;
            Cl[cf] := BrushColor;
            IE[cf] := ies;
            Inc(cf);
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, sx, sy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // sx, sy - left-top letter in sColors
        begin
            for i := 0 to 2 do
                for j := 0 to 2 do begin
                    Id00 := GetId(0,0);
                    Id02 := GetId(0,2);
                    Id04 := GetId(0,4);
                    Id11 := GetId(1,1);
                    Id13 := GetId(1,3);
                    Id20 := GetId(2,0);
                    Id22 := GetId(2,2);
                    Id24 := GetId(2,4);
                    Id31 := GetId(3,1);
                    Id33 := GetId(3,3);
                    Id40 := GetId(4,0);
                    Id42 := GetId(4,2);
                    Id44 := GetId(4,4);

                    BrushColor := GetColor(0,0);
                    Polygon( Id02 + Id20 + Id00, 1);
                    Polygon( Id02 + Id13 + Id22 + Id11, 15);

                    BrushColor := GetColor(0,1);
                    Polygon( Id24 + Id02 + Id04, 1);
                    Polygon( Id24 + Id33 + Id22 + Id13, 15);

                    BrushColor := GetColor(1,1);
                    Polygon( Id42 + Id24 + Id44, 1);
                    Polygon( Id42 + Id31 + Id22 + Id33, 15);

                    BrushColor := GetColor(1,0);
                    Polygon( Id20 + Id42 + Id40, 1);
                    Polygon( Id20 + Id11 + Id22 + Id31, 15);
                end;
        end;

        cf := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   6, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   6, 4); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 4); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,  11, 4); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  16, 4); // back
        MakeSide( 0, 0, 0,  1, 0, 0,  0, 1, 0,   6, 8); // bottom
